INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 401, 0, 2, 24001, "アヤネ", 0, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 402, 0, 1, 24002, "アヤネ", 2.21, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 403, 0, 2, 24003, "アヤネ", 0, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 701, 0, 2, 24004, "アサヒ", 1.99, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 702, 0, 1, 24005, "アサヒ", 2.21, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 703, 0, 2, 24006, "アサヒ", 3.33, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 801, 0, 2, 24007, "部員３", 0, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 802, 0, 1, 24008, "部員３", 2.68, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 803, 0, 2, 24009, "部員３", 0, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 501, 0, 1, 24010, "", 0, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "やった！", 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 502, 0, 1, 24011, "", 0, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "勝ったよ！", 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 503, 0, 1, 24012, "", 0, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "いい調子！", 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 111, 0, 6, 24013, "ミサト", 5.33, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 112, 0, 1, 24014, "ミサト", 6.85, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 113, 0, 1, 24015, "ミサト", 3, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 611, 0, 1, 24016, "ダイチ", 6.11, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 192401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 612, 0, 1, 24017, "ダイチ", 6.75, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 192401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 613, 0, 2, 24018, "ダイチ", 0, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 192401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 211, 0, 2, 24019, "ハツネ", 4.52, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 113401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 212, 0, 2, 24020, "ハツネ", 3.89, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 113401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 213, 0, 1, 24021, "ハツネ", 13.49, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 113401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 311, 0, 1, 24022, "カヤ", 3.17, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 106501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 312, 0, 1, 24023, "カヤ", 4.42, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 106501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 313, 0, 6, 24024, "カヤ", 2.89, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 106501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 421, 0, 4, 24025, "アヤネ", 3.71, 24, 10046, "2020/07/31 12:00:00", 3, "2030/12/17 14:59:59", "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 721, 0, 2, 24026, "アサヒ", 5.1, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 821, 0, 1, 24027, "部員３", 4.34, 24, 10046, "2020/07/31 12:00:00", 3, "2030/12/17 14:59:59", "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 521, 0, 1, 24028, "", 0, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "いい勝負だったよ\nまたやろうね", 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 101, -360, 1, 24029, "ミサト", 5.62, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 102, -360, 1, 24030, "ミサト", 9.58, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 103, -360, 2, 24031, "ミサト", 0, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 104, -360, 2, 24032, "ミサト", 9.13, 24, 10046, "2020/07/31 12:00:00", 1, "2030/12/17 14:59:59", "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, 105, -360, 1, 24033, "ミサト", 8.27, 24, 10046, "2020/07/31 12:00:00", 2, "2030/12/17 14:59:59", "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 113501);
